<div class="top"><div><h2 style="margin:0">Notes</h2><span class="muted"><?= $arch ? 'Archived notes' : 'Quick notes and checklists. Shared notes are visible to all staff.' ?></span></div>
<form class="filters" method="get" style="margin:0"><input name="q" value="<?= e($q) ?>" placeholder="Search notes" aria-label="Search notes"><?= $arch ? '<input type="hidden" name="archived" value="1">' : '' ?><button class="btn alt sm">Search</button> <a class="btn alt sm" href="/staff/notes<?= $arch ? '' : '?archived=1' ?>"><?= $arch ? 'Back to notes' : 'Archive' ?></a></form></div>
<?php if (!$arch): ?><div class="card mb" style="max-width:640px"><form method="post" action="/staff/notes"><?= csrf_field() ?>
<input name="title" maxlength="160" placeholder="Title (optional)" aria-label="Title"><textarea name="body" rows="3" maxlength="20000" placeholder="Take a note... or choose Checklist and write one item per line" aria-label="Note"></textarea>
<div class="row" style="align-items:end"><div><label for="nk">Type</label><select id="nk" name="kind"><option value="text">Note</option><option value="list">Checklist</option></select></div><div><label for="nc">Colour</label><select id="nc" name="color"><?= options(NOTE_COLORS, 'none') ?></select></div><div><label style="font-weight:400"><input type="checkbox" name="shared" value="1" style="width:auto;margin:0 6px 0 0">Share with all staff</label></div><div style="flex:0"><button class="btn">Add</button></div></div></form></div><?php endif; ?>
<div class="notes"><?php foreach ($rows as $n): $mine = (int) $n['owner_id'] === (int) $u['id']; ?>
<div class="note-card c-<?= e($n['color']) ?>" id="n<?= (int) $n['id'] ?>"><?= $n['pinned'] ? '<span class="pill" style="float:right">Pinned</span>' : '' ?><?php if ($n['title']): ?><h3><?= e($n['title']) ?></h3><?php endif; ?>
<?php if ($n['kind'] === 'list'): foreach (note_items($n['items']) as $i => $it): ?><form method="post" action="/staff/notes/<?= (int) $n['id'] ?>" class="tick"><?= csrf_field() ?><input type="hidden" name="action" value="tick"><input type="hidden" name="i" value="<?= $i ?>"><label style="font-weight:400;margin:0"><input type="checkbox" data-autosubmit style="width:auto;margin:0 6px 0 0" <?= $it['d'] ? 'checked' : '' ?>><span style="<?= $it['d'] ? 'text-decoration:line-through;opacity:.6' : '' ?>"><?= e($it['t']) ?></span></label></form><?php endforeach; else: ?><div class="md"><?= nl2br(e((string) $n['body'])) ?></div><?php endif; ?>
<p class="who" style="margin:8px 0 0;font-size:.78rem"><?= $n['shared'] ? 'Shared &middot; ' : '' ?><?= e($n['oname']) ?> &middot; <?= e(fmt_dt($n['updated_at'])) ?><?= $n['files'] ? ' &middot; ' . (int) $n['files'] . ' file(s)' : '' ?></p>
<div class="mt"><a class="btn alt sm" href="/staff/notes/<?= (int) $n['id'] ?>"><?= $mine ? 'Edit' : 'Open' ?></a><?php if ($mine): ?> <form method="post" action="/staff/notes/<?= (int) $n['id'] ?>" class="inline"><?= csrf_field() ?><button class="btn alt sm" name="action" value="pin"><?= $n['pinned'] ? 'Unpin' : 'Pin' ?></button> <button class="btn alt sm" name="action" value="archive"><?= $n['archived'] ? 'Restore' : 'Archive' ?></button></form><?php endif; ?></div></div>
<?php endforeach; if (!$rows): ?><p class="muted"><?= $q !== '' ? 'No notes match.' : 'No notes yet.' ?></p><?php endif; ?></div>
